// ControlPlaneHandler is an implementation of the ares.v1.ControlPlane service.
type ControlPlaneHandler interface {
	ListModules(context.Context, *connect.Request[v1.ListModulesRequest]) (*connect.Response[v1.ListModulesResponse], error)
	CreateTenant(context.Context, *connect.Request[v1.CreateTenantRequest]) (*connect.Response[v1.Tenant], error)
	ListTenants(context.Context, *connect.Request[v1.ListTenantsRequest]) (*connect.Response[v1.ListTenantsResponse], error)
	CreateEngagement(context.Context, *connect.Request[v1.CreateEngagementRequest]) (*connect.Response[v1.Engagement], error)
	ListEngagements(context.Context, *connect.Request[v1.ListEngagementsRequest]) (*connect.Response[v1.ListEngagementsResponse], error)
	GetEngagement(context.Context, *connect.Request[v1.GetEngagementRequest]) (*connect.Response[v1.Engagement], error)
	SetScope(context.Context, *connect.Request[v1.SetScopeRequest]) (*connect.Response[v1.Engagement], error)
	Authorize(context.Context, *connect.Request[v1.AuthorizeRequest]) (*connect.Response[v1.Engagement], error)
	Halt(context.Context, *connect.Request[v1.HaltRequest]) (*connect.Response[v1.Engagement], error)
	DispatchJob(context.Context, *connect.Request[v1.DispatchJobRequest]) (*connect.Response[v1.DispatchJobResponse], error)
	GetJob(context.Context, *connect.Request[v1.GetJobRequest]) (*connect.Response[v1.JobOutcome], error)
	// ListJobs lists an engagement's completed jobs, newest first, for the
	// "earlier tests" view.
	ListJobs(context.Context, *connect.Request[v1.ListJobsRequest]) (*connect.Response[v1.ListJobsResponse], error)
	// ListFindings lists an engagement's (or the whole workspace's) findings,
	// deduplicated across re-runs.
	ListFindings(context.Context, *connect.Request[v1.ListFindingsRequest]) (*connect.Response[v1.ListFindingsResponse], error)
	// SetFindingStatus records the operator's triage state for a finding.
	SetFindingStatus(context.Context, *connect.Request[v1.SetFindingStatusRequest]) (*connect.Response[v1.Finding], error)
	// RecheckFinding reproduces a finding's proof on demand: it dispatches the
	// finding's narrowed re-check probe through the normal scope gate and returns
	// the job it started. Reproduction is confirmed when that job emits a proof
	// with the same claim.
	RecheckFinding(context.Context, *connect.Request[v1.RecheckFindingRequest]) (*connect.Response[v1.RecheckFindingResponse], error)
	// GetProofArtifact returns a finding's proof as a downloadable JSON record
	// plus the audit entry (seq and chain hash) that anchors its fingerprint, so a
	// user can verify it offline.
	GetProofArtifact(context.Context, *connect.Request[v1.GetProofArtifactRequest]) (*connect.Response[v1.GetProofArtifactResponse], error)
	GetAudit(context.Context, *connect.Request[v1.GetAuditRequest]) (*connect.Response[v1.GetAuditResponse], error)
	GenerateReport(context.Context, *connect.Request[v1.GenerateReportRequest]) (*connect.Response[v1.GenerateReportResponse], error)
	GetDetectionSummary(context.Context, *connect.Request[v1.GetDetectionSummaryRequest]) (*connect.Response[v1.DetectionSummary], error)
	SetDetection(context.Context, *connect.Request[v1.SetDetectionRequest]) (*connect.Response[v1.DetectionSummary], error)
	// GetRiskPicture correlates an engagement's findings into prioritized attack paths.
	GetRiskPicture(context.Context, *connect.Request[v1.GetRiskPictureRequest]) (*connect.Response[v1.RiskPicture], error)
	ListPurpleTemplates(context.Context, *connect.Request[v1.ListPurpleTemplatesRequest]) (*connect.Response[v1.ListPurpleTemplatesResponse], error)
	GetPurpleTemplate(context.Context, *connect.Request[v1.GetPurpleTemplateRequest]) (*connect.Response[v1.PurpleTemplate], error)
	// Advise returns grounded AI advisory text for an engagement. It is strictly
	// advisory: it never dispatches a job, changes scope, or bypasses the
	// authorization gate. When no AI provider is configured the feature is simply
	// off (enabled=false). Sending engagement data to the provider requires the
	// operator's per-engagement opt-in.
	Advise(context.Context, *connect.Request[v1.AdviseRequest]) (*connect.Response[v1.AdviseResponse], error)
	// Settings are configured in-app, per workspace: the AI advisory provider and
	// the OSINT provider credentials. Secrets are write-only — GetSettings never
	// returns a secret value, only whether it is set and a masked hint. Stored
	// settings layer over environment-variable fallbacks.
	GetSettings(context.Context, *connect.Request[v1.GetSettingsRequest]) (*connect.Response[v1.SettingsView], error)
	UpdateSettings(context.Context, *connect.Request[v1.UpdateSettingsRequest]) (*connect.Response[v1.SettingsView], error)
	// TestAIProvider verifies that an AI provider configuration can authenticate
	// and reach its model, with a minimal probe. It can test the saved settings or
	// unsaved form values, and never stores anything. No engagement data is sent.
	TestAIProvider(context.Context, *connect.Request[v1.TestAIProviderRequest]) (*connect.Response[v1.TestAIProviderResponse], error)
	// First-run setup. The app is gated to /setup until GetSetupStatus reports
	// done. CommitSetup is the single atomic provisioning call; nothing is
	// persisted before it, and it refuses to run on an initialized install.
	GetSetupStatus(context.Context, *connect.Request[v1.GetSetupStatusRequest]) (*connect.Response[v1.SetupStatus], error)
	TestDatabaseConnection(context.Context, *connect.Request[v1.TestDatabaseConnectionRequest]) (*connect.Response[v1.TestDatabaseConnectionResponse], error)
	CommitSetup(context.Context, *connect.Request[v1.CommitSetupRequest]) (*connect.Response[v1.CommitSetupResponse], error)
	// Built-in email + password authentication. Login opens a server-side session
	// and returns a bearer token; CurrentUser and Logout act on that token.
	Login(context.Context, *connect.Request[v1.LoginRequest]) (*connect.Response[v1.LoginResponse], error)
	Logout(context.Context, *connect.Request[v1.LogoutRequest]) (*connect.Response[v1.LogoutResponse], error)
	CurrentUser(context.Context, *connect.Request[v1.CurrentUserRequest]) (*connect.Response[v1.UserInfo], error)
	// User management (the People screen). Authorized by the caller's role:
	// super-admins manage any workspace; owners/admins manage users within their
	// own workspace, and cannot grant a role above their own.
	ListUsers(context.Context, *connect.Request[v1.ListUsersRequest]) (*connect.Response[v1.ListUsersResponse], error)
	CreateUser(context.Context, *connect.Request[v1.CreateUserRequest]) (*connect.Response[v1.UserInfo], error)
	SetUserRole(context.Context, *connect.Request[v1.SetUserRoleRequest]) (*connect.Response[v1.UserInfo], error)
	SetUserDisabled(context.Context, *connect.Request[v1.SetUserDisabledRequest]) (*connect.Response[v1.UserInfo], error)
	// Agent management (the engagement's "Agents" view). An agent is a transparent,
	// authorized component deployed inside a target's network/host; these operator
	// calls mint and manage its install keys and the agents themselves. The agent
	// itself speaks the separate AgentService (agent.proto). See
	// ares-design/agent-design.md and agent-prd.md.
	//
	// MintAgentKey records the required host-owner permission and creates a
	// one-time install key scoped to the engagement with a capability allow-list.
	MintAgentKey(context.Context, *connect.Request[v1.MintAgentKeyRequest]) (*connect.Response[v1.MintAgentKeyResponse], error)
	// CancelAgentKey withdraws an unused install key.
	CancelAgentKey(context.Context, *connect.Request[v1.CancelAgentKeyRequest]) (*connect.Response[v1.CancelAgentKeyResponse], error)
	// ListAgentKeys lists the engagement's unused install keys.
	ListAgentKeys(context.Context, *connect.Request[v1.ListAgentKeysRequest]) (*connect.Response[v1.ListAgentKeysResponse], error)
	// ListAgents lists the engagement's agents with status, host facts, consent and
	// capability allow-list.
	ListAgents(context.Context, *connect.Request[v1.ListAgentsRequest]) (*connect.Response[v1.ListAgentsResponse], error)
	GetAgent(context.Context, *connect.Request[v1.GetAgentRequest]) (*connect.Response[v1.AgentView], error)
	// RemoveAgent revokes an agent immediately; it self-uninstalls on next contact.
	// Findings it already sent are kept.
	RemoveAgent(context.Context, *connect.Request[v1.RemoveAgentRequest]) (*connect.Response[v1.RemoveAgentResponse], error)
	// DispatchAgentJob queues an authorized check for an agent to run from inside
	// the network. The server gate-checks it (engagement runnable, agent bound,
	// module on the agent's capability allow-list) and sends the agent the
	// engagement scope snapshot; the agent re-enforces the scope locally before
	// touching any target. Results flow back into the same findings pipeline.
	DispatchAgentJob(context.Context, *connect.Request[v1.DispatchAgentJobRequest]) (*connect.Response[v1.DispatchAgentJobResponse], error)
	// Test intensity and consent. Each engagement allows tests up to one of the
	// engine's consent levels: 1 safe proof (default, always on), 2 active
	// confirmation (per-engagement opt-in), 3 intrusive but recoverable (also
	// needs a recorded, single-use approval per technique and per target before
	// each run). There is no level above 3: nothing irreversible can be allowed.
	//
	// GetTestConsent returns the engagement's level, the tests above safe proof
	// with what each does, and the approvals on file.
	GetTestConsent(context.Context, *connect.Request[v1.GetTestConsentRequest]) (*connect.Response[v1.TestConsent], error)
	// SetTestIntensity sets the highest level the engagement allows. Lowering it
	// withdraws unused approvals. Managers only. Audited.
	SetTestIntensity(context.Context, *connect.Request[v1.SetTestIntensityRequest]) (*connect.Response[v1.TestConsent], error)
	// ApproveTechnique records a single-use approval for one intrusive test
	// against one in-scope target. Managers only. Audited.
	ApproveTechnique(context.Context, *connect.Request[v1.ApproveTechniqueRequest]) (*connect.Response[v1.TechniqueApproval], error)
	// DeclineTechnique records that an intrusive test was not allowed. Audited.
	DeclineTechnique(context.Context, *connect.Request[v1.DeclineTechniqueRequest]) (*connect.Response[v1.DeclineTechniqueResponse], error)
	// WithdrawApproval takes back an approval that has not been used. Audited.
	WithdrawApproval(context.Context, *connect.Request[v1.WithdrawApprovalRequest]) (*connect.Response[v1.TestConsent], error)
	// StopJob stops one running test at once (the resilience test's "Stop now")
	// without stopping the engagement. Audited.
	StopJob(context.Context, *connect.Request[v1.StopJobRequest]) (*connect.Response[v1.StopJobResponse], error)
}

